$pmo=User::where('system_role','pmo')->where('account_status','active')->firstOrFail();$people=User::where('system_role','user')->where('account_status','active')->take(2)->get();$pm=$people[0];$member=$people[1];$sub=Subsidiary::where('status','active')->firstOrFail();$role=ProjectRole::where('slug','team')->firstOrFail();$service=app(App\Services\ProjectService::class);$access=app(App\Services\Access::class);$controller=app(App\Http\Controllers\ProjectController::class);$templates=app(App\Http\Controllers\TemplateController::class);view()->share('errors',new Illuminate\Support\ViewErrorBag());
