$request=function($uri,$method='GET',$data=[],$actor=null)use($pmo,$app){$actor=$actor??$pmo;$app['auth']->forgetGuards();$app['auth']->guard()->setUser($actor);$r=Request::create('http://127.0.0.1:8000'.$uri,$method,$data);$r->setUserResolver(fn()=>$actor);$r->setLaravelSession(app('session')->driver());$route=app('router')->getRoutes()->match($r);$r->setRouteResolver(fn()=>$route);$app->instance('request',$r);return $r;};
