$projectCount=Project::count();$templateCount=ProjectTemplate::count();DB::beginTransaction();
try{
 $makeTemplate=function($name,$context=[])use($request,$templates){$r=$request('/templates','POST',array_merge(['name'=>$name,'category'=>'General','estimated_duration'=>3,'duration_unit'=>'working_days','reference_start_date'=>'2026-11-09','tasks'=>[['code'=>'A1','title'=>'Prepare delivery','start_date'=>'2026-11-09','end_date'=>'2026-11-11','duration_days'=>3]]],$context));$r->headers->set('Accept','application/json');$response=$templates->store($r);return $response->getData(true);};
