 $data=['name'=>'UI QA saved draft','description'=>'Saved project scope','subsidiary_id'=>$sub->id,'starts_on'=>'2026-11-09','ends_on'=>'2026-11-27','mode'=>'template','project_template_id'=>$template->id,'pm_user_id'=>$pm->id,'members'=>[['user_id'=>$member->id,'project_role_id'=>$role->id]],'status_override'=>'draft'];
 $draft=$service->create($data,$pmo);$taskIds=$draft->tasks()->pluck('id')->all();$code=$draft->code;$id=$draft->id;$draft->tasks()->first()->assignees()->sync([$member->id]);
 $check($draft->status==='draft' && count($taskIds)===1 && !$draft->invitations()->exists(),'Draft stores its prepared task plan without sending an invitation');
 $r=$request('/projects/create?draft='.$id);$html=$controller->create($r,$access)->render();$check(str_contains($html,'value="UI QA saved draft"')&&str_contains($html,'Saved project scope')&&str_contains($html,'value="'.$pm->id.'"')&&str_contains($html,'/projects/'.$id.'/draft'),'Create interface is prefilled and posts to the existing draft');$saveHtml('pmo-draft-create.html',$html);
 $html=$controller->index($request('/projects'),$access)->render();$check(str_contains($html,'draft='.$id)&&str_contains($html,'project-draft-create'),'Draft list/grid display Create project');$saveHtml('pmo-draft-library.html',$html);
 try{$controller->create($request('/projects/create?draft='.$id,'GET',[],$member),$access);throw new Exception('Unauthorized draft was accessible');}catch(Symfony\Component\HttpKernel\Exception\HttpException $e){$check($e->getStatusCode()===403,'Another user cannot resume the draft');}
 $request('/projects');$saved=$service->resumeDraft($draft,$data,$pmo);$check($saved->id===$id&&$saved->code===$code&&$saved->tasks()->pluck('id')->all()===$taskIds&&Project::count()===$projectCount+1,'Saving draft retains project identity, task IDs and code');
 $check($saved->tasks()->first()->assignees()->where('users.id',$member->id)->exists(),'Unchanged draft team retains task assignment');
 $flow='99000000-0000-4000-8000-000000000099';$context=['select_for_project'=>1,'project_flow'=>$flow,'draft'=>$id];$new=$makeTemplate('UI QA newly chosen template',$context);parse_str(parse_url($new['redirect'],PHP_URL_QUERY),$query);$check(($query['draft']??null)===(string)$id&&($query['project_flow']??null)===$flow&&($query['template_id']??null)===(string)$new['template_id'],'New template returns to its original draft and form context');
 $r=$request('/templates?'.http_build_query($context));$html=$templates->index($r)->render();$check(str_contains($html,'btn-select-template')&&str_contains($html,'name="project_flow"')&&str_contains($html,'project_flow='.$flow),'Library selection, filtering and Create Template preserve project context');$saveHtml('pmo-template-selection.html',$html);
 $r=$request('/templates/create?'.http_build_query($context));$saveHtml('pmo-template-create-selection.html',$templates->create($r)->render());
 $newContext=['select_for_project'=>1,'project_flow'=>$flow];
 $r=$request('/templates?'.http_build_query($newContext));$saveHtml('pmo-new-template-selection.html',$templates->index($r)->render());
 $r=$request('/templates/create?'.http_build_query($newContext));$saveHtml('pmo-new-template-create-selection.html',$templates->create($r)->render());
 $r=$request('/projects/create?'.http_build_query(['project_flow'=>$flow,'template_id'=>$new['template_id']]));$saveHtml('pmo-new-template-return.html',$controller->create($r,$access)->render());
 file_put_contents(__DIR__.'/draft-template-test-data.json',json_encode(['draft'=>$id,'flow'=>$flow,'template'=>$new['template_id']]));
 $r=$request('/projects/create?'.http_build_query(['draft'=>$id,'project_flow'=>$flow,'template_id'=>$new['template_id']]));$saveHtml('pmo-draft-template-return.html',$controller->create($r,$access)->render());
 $changed=$data;$changed['project_template_id']=$new['template_id'];try{$service->resumeDraft($draft,$changed,$pmo);throw new Exception('Unconfirmed replacement accepted');}catch(Illuminate\Validation\ValidationException $e){$check($draft->tasks()->pluck('id')->all()===$taskIds,'Template replacement requires explicit confirmation');}
 $draft->tasks()->first()->update(['progress'=>25]);$changed['replace_draft_plan']=true;try{$service->resumeDraft($draft,$changed,$pmo);throw new Exception('Active task plan replaced');}catch(Illuminate\Validation\ValidationException $e){$check($draft->tasks()->pluck('id')->all()===$taskIds,'Task activity blocks plan replacement');}$draft->tasks()->first()->update(['progress'=>0]);
 $replacement=$service->create($data,$pmo);$replacementIds=$replacement->tasks()->pluck('id')->all();$replaced=$service->resumeDraft($replacement,$changed,$pmo);$check($replaced->status==='draft'&&$replaced->project_template_id===$new['template_id']&&$replaced->tasks()->count()===1&&$replaced->tasks()->pluck('id')->all()!==$replacementIds,'Confirmed pristine draft can adopt the newly selected template');
 $submit=$data;unset($submit['status_override']);$submit['action']='create';$response=$controller->saveDraft($request('/projects/'.$id.'/draft','POST',$submit),$draft,$service,$access);$final=$draft->fresh();$check($response->isRedirect()&&$final->id===$id&&$final->status==='pending'&&$final->invitations()->where('status','pending')->count()===1&&$final->tasks()->pluck('id')->all()===$taskIds,'Create converts the same draft to pending approval exactly once without duplicate tasks');
 try{$controller->saveDraft($request('/projects/'.$id.'/draft','POST',$submit),$draft->fresh(),$service,$access);throw new Exception('Duplicate draft submit accepted');}catch(Symfony\Component\HttpKernel\Exception\HttpException $e){$check($e->getStatusCode()===409&&$final->invitations()->count()===1,'A repeated submit cannot create another project or invitation');}
}finally{DB::rollBack();}
$check(Project::count()===$projectCount && ProjectTemplate::count()===$templateCount,'All project/template fixtures rolled back; no mail sent');
